/** Wizard field inventory: NTSSA sizes, at least one pitch per league, a drag-map. */

import { parseAvailability } from "./dates";
import { NTSSA_DRAW, type NtssaClass } from "./survey/units";
import { norm, type Field, type League } from "./model";

export const FIELD_CLASSES: NtssaClass[] = ["small", "medium", "nine", "full"];
const AVAILABLE = "Saturday 8:00–18:00";
const GAP_YD = 8;
const MARGIN_YD = 10;

export function isNtssaClass(s: string): s is NtssaClass {
  return FIELD_CLASSES.includes(s as NtssaClass);
}

export function classForBracket(bracket: string, fieldClasses: string[]): NtssaClass {
  const listed = fieldClasses.map((c) => c.toLowerCase()).find(isNtssaClass);
  if (listed) return listed;
  const n = Number((bracket.match(/(\d+)\s*u/i) || [])[1]);
  if (n && n <= 8) return "small";
  if (n && n <= 10) return "medium";
  if (n && n <= 12) return "nine";
  return "full";
}

export function neededClasses(league: League): NtssaClass[] {
  const set = new Set<NtssaClass>();
  for (const ag of league.ageGroups) {
    if (!ag.name) continue;
    if (!league.teams.some((t) => t.bracket === ag.name)) continue;
    set.add(classForBracket(ag.name, ag.fieldClasses));
  }
  if (!set.size) {
    for (const ag of league.ageGroups) {
      if (ag.name) set.add(classForBracket(ag.name, ag.fieldClasses));
    }
  }
  if (!set.size) set.add("small");
  return FIELD_CLASSES.filter((c) => set.has(c));
}

/** Our grass — not a pitch we planted at the other org so an away Saturday can sit there. */
export function isHomeWizardPitch(league: League, f: { campus: string }): boolean {
  const campus = f.campus || "";
  const camp = league.campuses.find((c) => norm(c.name) === norm(campus));
  if (camp?.association) {
    const a = league.associations.find((x) => norm(x.name) === norm(camp.association || ""));
    if (a) return !!a.controlled;
  }
  const byHome = league.associations.find((a) => a.homeCampus && norm(a.homeCampus) === norm(campus));
  if (byHome) return !!byHome.controlled;
  return /van/i.test(campus) || !campus;
}

export function fieldsCoverBrackets(league: League): { ok: boolean; missing: string[] } {
  const missing: string[] = [];
  for (const ag of league.ageGroups) {
    if (!ag.name) continue;
    if (!league.teams.some((t) => t.bracket === ag.name)) continue;
    const want = classForBracket(ag.name, ag.fieldClasses);
    const hit = league.fields.some((f) => isNtssaClass(f.type) && f.type === want && isHomeWizardPitch(league, f));
    if (!hit) missing.push(`${ag.name} needs a ${want} pitch (${NTSSA_DRAW[want].label})`);
  }
  return { ok: !missing.length, missing };
}

export function countOfClass(league: League, cls: NtssaClass): number {
  return league.fields.filter((f) => norm(f.type) === cls && isHomeWizardPitch(league, f)).length;
}

function nextName(league: League, campus: string, cls: NtssaClass): string {
  const label = NTSSA_DRAW[cls].ages;
  const base = `${campus} ${label}`;
  if (!league.fields.some((f) => norm(f.name) === norm(base))) return base;
  let n = 2;
  while (league.fields.some((f) => norm(f.name) === norm(`${base} ${n}`))) n += 1;
  return `${base} ${n}`;
}

function campusName(league: League): string {
  return league.campuses[0]?.name || league.fields[0]?.campus || "Van Complex";
}

function placeNew(league: League, cls: NtssaClass): { east: number; south: number; heading: number } {
  const draw = NTSSA_DRAW[cls];
  const existing = league.fields.filter((f) => isHomeWizardPitch(league, f) && f.mapEastYd != null && f.mapSouthYd != null);
  if (!existing.length) {
    return { east: MARGIN_YD + draw.widthYd / 2, south: MARGIN_YD + draw.lengthYd / 2, heading: 90 };
  }
  let maxX = 0;
  for (const f of existing) {
    const w = isNtssaClass(f.type) ? NTSSA_DRAW[f.type].widthYd : 25;
    maxX = Math.max(maxX, (f.mapEastYd || 0) + w / 2);
  }
  return { east: maxX + GAP_YD + draw.widthYd / 2, south: MARGIN_YD + draw.lengthYd / 2, heading: 90 };
}

export function addWizardField(league: League, cls: NtssaClass, campus = campusName(league)): Field {
  const windows = parseAvailability(AVAILABLE);
  const pos = placeNew(league, cls);
  const field: Field = {
    name: nextName(league, campus, cls),
    type: cls,
    campus,
    parking: "",
    availableRaw: AVAILABLE,
    windows,
    assumed: true,
    mapEastYd: pos.east,
    mapSouthYd: pos.south,
    headingDeg: pos.heading,
  };
  league.fields.push(field);
  return field;
}

export function removeWizardField(league: League, name: string): boolean {
  const i = league.fields.findIndex((f) => f.name === name);
  if (i < 0) return false;
  const cls = league.fields[i].type;
  const remaining = league.fields.filter(
    (f, k) => k !== i && norm(f.type) === norm(cls) && isHomeWizardPitch(league, f),
  ).length;
  const need = neededClasses(league);
  if (isNtssaClass(cls) && need.includes(cls) && remaining < 1) return false;
  league.fields.splice(i, 1);
  return true;
}

export function setClassCount(league: League, cls: NtssaClass, n: number): void {
  const want = Math.max(0, Math.round(n));
  const need = neededClasses(league).includes(cls) ? Math.max(1, want) : want;
  let have = countOfClass(league, cls);
  while (have < need) {
    addWizardField(league, cls);
    have += 1;
  }
  while (have > need) {
    const idx = [...league.fields].reverse().findIndex((f) => norm(f.type) === cls && isHomeWizardPitch(league, f));
    if (idx < 0) break;
    const real = league.fields.length - 1 - idx;
    if (!removeWizardField(league, league.fields[real].name)) break;
    have -= 1;
  }
}

export function moveWizardField(league: League, name: string, eastYd: number, southYd: number): boolean {
  const f = league.fields.find((x) => x.name === name);
  if (!f) return false;
  f.mapEastYd = eastYd;
  f.mapSouthYd = southYd;
  f.assumed = false;
  return true;
}

export function setWizardCampus(league: League, campus: string): void {
  const name = campus.trim() || "Van Complex";
  for (const f of league.fields) {
    if (!isHomeWizardPitch(league, f)) continue;
    f.campus = name;
  }
  if (!league.campuses.length) {
    league.campuses.push({ name, association: "Van Rec", street: "", lat: undefined, lng: undefined });
  } else {
    league.campuses[0].name = name;
  }
}

function placeholdersOnly(league: League): boolean {
  if (!league.fields.length) return true;
  return league.fields.every((f) => /^not listed yet/i.test(f.name));
}

/** One NTSSA pitch per league class. Replaces "Not listed yet" placeholders. */
export function ensureWizardFields(league: League): boolean {
  if (!placeholdersOnly(league) && fieldsCoverBrackets(league).ok) {
    for (const f of league.fields) {
      if (!isHomeWizardPitch(league, f)) continue;
      if (f.mapEastYd == null || f.mapSouthYd == null) {
        const pos = placeNew(league, isNtssaClass(f.type) ? f.type : "small");
        f.mapEastYd = pos.east;
        f.mapSouthYd = pos.south;
        f.headingDeg = f.headingDeg ?? pos.heading;
      }
    }
    return false;
  }
  const campus = campusName(league);
  const keepGuest = league.fields.filter((f) => !isHomeWizardPitch(league, f));
  league.fields = keepGuest;
  for (const cls of neededClasses(league)) addWizardField(league, cls, campus);
  return true;
}
