/** Typeahead index over the loaded season — teams, people, fields, campuses, dates, games. */

import { formatSheetDate, formatSheetTime } from "./dates";
import { familyLabel, printName, teamLabel, type Configuration, type League } from "./model";
import { sheetClubName, sheetLocation } from "./schedule-sheet";

export type SearchKind = "team" | "person" | "field" | "campus" | "date" | "game";

export interface SearchHit {
  kind: SearchKind;
  id: string;
  label: string;
  hint: string;
  score: number;
  gameId?: string;
  dateIso?: string;
  bracket?: string;
  inspect?: string;
  person?: string;
}

function scoreMatch(q: string, text: string): number {
  const needle = q.toLowerCase().trim();
  const n = String(text || "").toLowerCase();
  if (!needle || !n) return 0;
  if (n === needle) return 100;
  if (n.startsWith(needle)) return 86;
  const i = n.indexOf(needle);
  if (i === 0) return 80;
  if (i > 0) return Math.max(40, 70 - Math.min(i, 25));
  if (n.split(/[\s·\-/]+/).some((t) => t.startsWith(needle))) return 55;
  return 0;
}

function best(q: string, parts: Array<string | undefined | null>): number {
  let top = 0;
  for (const p of parts) {
    if (!p) continue;
    const s = scoreMatch(q, p);
    if (s > top) top = s;
  }
  return top;
}

const KIND_RANK: Record<SearchKind, number> = {
  game: 6,
  team: 5,
  person: 4,
  field: 3,
  campus: 3,
  date: 2,
};

export function searchSeason(league: League, cfg: Configuration | undefined, q: string): SearchHit[] {
  const query = q.trim();
  if (!query || query.length < 1) return [];
  const hits: SearchHit[] = [];
  const push = (hit: SearchHit) => {
    if (hit.score >= 40) hits.push(hit);
  };

  for (const t of league.teams) {
    const label = teamLabel(t);
    const club = sheetClubName(league, label, t.bracket);
    const score = best(query, [t.name, label, club, t.bracket, t.association, t.jersey]);
    push({
      kind: "team",
      id: `team:${label}`,
      label: club,
      hint: `${t.bracket} · ${t.association}`,
      score,
      bracket: t.bracket,
      inspect: "teams",
    });
  }

  const people = new Map<string, { name: string; hint: string }>();
  const addPerson = (name: string, hint: string) => {
    const key = name.trim();
    if (!key || people.has(key)) return;
    people.set(key, { name: key, hint });
  };
  for (const s of league.staff) addPerson(printName(s), "staff");
  for (const t of league.teams) {
    if (t.coach) addPerson(printName(t.coach), `coach · ${teamLabel(t)}`);
    if (t.assistant) addPerson(printName(t.assistant), `assistant · ${teamLabel(t)}`);
  }
  for (const f of league.families) {
    const fam = familyLabel(f);
    for (const p of f.parents) addPerson(printName(p), `parent · ${fam}`);
    for (const c of f.children) addPerson(printName(c), `${c.bracket} ${c.team} · ${fam}`);
  }
  for (const g of cfg?.games || []) {
    if (g.center) addPerson(g.center, "center referee");
    for (const a of g.assistants) addPerson(a, "assistant referee");
  }
  for (const [name, meta] of people) {
    push({
      kind: "person",
      id: `person:${name}`,
      label: name,
      hint: meta.hint,
      score: best(query, [name, meta.hint]),
      inspect: "person",
      person: name,
    });
  }

  for (const f of league.fields) {
    push({
      kind: "field",
      id: `field:${f.name}`,
      label: f.name,
      hint: `${f.campus} · ${f.type}`,
      score: best(query, [f.name, f.campus, f.type, f.parking]),
      inspect: "fields",
    });
  }

  for (const c of league.campuses) {
    push({
      kind: "campus",
      id: `campus:${c.name}`,
      label: c.name,
      hint: c.street || c.association || "campus",
      score: best(query, [c.name, c.street, c.association]),
      inspect: "campuses",
    });
  }

  const dates = new Set<string>();
  for (const g of cfg?.games || []) dates.add(g.dateIso);
  for (const iso of dates) {
    const sheet = formatSheetDate(iso);
    push({
      kind: "date",
      id: `date:${iso}`,
      label: sheet,
      hint: iso,
      score: best(query, [sheet, iso]),
      dateIso: iso,
      inspect: "schedule",
    });
  }

  for (const g of cfg?.games || []) {
    const home = sheetClubName(league, g.home, g.ageGroup);
    const away = sheetClubName(league, g.away, g.ageGroup);
    const loc = sheetLocation(league, g.campus, g.field);
    const time = formatSheetTime(g.kickoff);
    const date = formatSheetDate(g.dateIso);
    push({
      kind: "game",
      id: `game:${g.id}`,
      label: `${home} vs ${away}`,
      hint: `${date} ${time} · ${loc}`,
      score: best(query, [home, away, g.home, g.away, loc, g.field, g.campus, time, date, g.kickoff, g.ageGroup, g.center]),
      gameId: g.id,
      dateIso: g.dateIso,
      bracket: g.ageGroup,
      inspect: "schedule",
    });
  }

  hits.sort((a, b) => b.score - a.score || KIND_RANK[b.kind] - KIND_RANK[a.kind] || a.label.localeCompare(b.label));
  const seen = new Set<string>();
  const out: SearchHit[] = [];
  for (const h of hits) {
    if (seen.has(h.id)) continue;
    seen.add(h.id);
    out.push(h);
    if (out.length >= 10) break;
  }
  return out;
}
