/** Survey overlays become league Field rows. Excel-imported grass is kept. */

import { parseAvailability } from "../dates";
import { norm, type Field, type League } from "../model";
import { photoCalibrated } from "./geometry";
import type { AssociationSurvey, SurveyOverlay } from "./types";

function fieldFromOverlay(o: SurveyOverlay, created: boolean): Field {
  return {
    name: o.fieldName.trim(),
    type: o.ntssaClass,
    campus: o.campus.trim(),
    parking: o.parking.trim(),
    availableRaw: o.availableRaw.trim(),
    windows: parseAvailability(o.availableRaw),
    surveyOverlayId: o.id,
    surveyCreated: created,
  };
}

export function overlayReady(o: SurveyOverlay, survey: AssociationSurvey): boolean {
  if (!o.fieldName.trim()) return false;
  const photo = survey.photos.find((p) => p.id === o.photoId);
  return !!photo && photoCalibrated(photo);
}

export function applyOverlaysToFields(league: League, survey: AssociationSurvey): Field[] {
  const live = new Set(survey.overlays.filter((o) => overlayReady(o, survey)).map((o) => o.id));
  const fields = league.fields
    .filter((f) => {
      if (!f.surveyOverlayId) return true;
      if (live.has(f.surveyOverlayId)) return true;
      return !f.surveyCreated;
    })
    .map((f) => {
      const copy: Field = { ...f, windows: f.windows.map((w) => ({ ...w })) };
      if (copy.surveyOverlayId && !live.has(copy.surveyOverlayId)) delete copy.surveyOverlayId;
      return copy;
    });
  for (const o of survey.overlays) {
    if (!overlayReady(o, survey)) continue;
    const next = fieldFromOverlay(o, true);
    const byOverlay = fields.find((f) => f.surveyOverlayId === o.id);
    const byName = fields.find((f) => norm(f.name) === norm(next.name));
    const target = byOverlay || byName;
    if (target) {
      target.name = next.name;
      target.type = next.type;
      target.campus = next.campus || target.campus;
      target.parking = next.parking || target.parking;
      target.availableRaw = next.availableRaw || target.availableRaw;
      target.windows = next.windows.length ? next.windows : target.windows;
      target.surveyOverlayId = o.id;
    } else {
      fields.push(next);
    }
  }
  return fields;
}
