/** Length math. Canonical unit is the integer inch. Pixels are never stored as truth. */

export const INCHES_PER_FOOT = 12;
export const INCHES_PER_YARD = 36;

export type NtssaClass = "small" | "medium" | "nine" | "full";

/** Touchline × goal-line in yards. Matches NTSSA 4v4/7v7/9v9 and the 11v11 midpoint used on Field types. */
export const NTSSA_DRAW: Record<
  NtssaClass,
  { lengthYd: number; widthYd: number; label: string; ages: string }
> = {
  small: { lengthYd: 35, widthYd: 25, label: "4v4", ages: "6U/8U" },
  medium: { lengthYd: 65, widthYd: 45, label: "7v7", ages: "10U" },
  nine: { lengthYd: 80, widthYd: 55, label: "9v9", ages: "12U" },
  full: { lengthYd: 110, widthYd: 70, label: "11v11", ages: "14U/16U" },
};

/** USSF/NTSSA 11v11 legal window. */
export const FULL_RANGE_YD = { lengthMin: 100, lengthMax: 120, widthMin: 50, widthMax: 80 };

export function yardsToInches(yd: number): number {
  return Math.round(yd * INCHES_PER_YARD);
}

export function inchesToYards(inches: number): number {
  return inches / INCHES_PER_YARD;
}

export function classSize(cls: NtssaClass): { lengthInches: number; widthInches: number } {
  const d = NTSSA_DRAW[cls];
  return { lengthInches: yardsToInches(d.lengthYd), widthInches: yardsToInches(d.widthYd) };
}

export function splitFeetInches(totalInches: number): { feet: number; inches: number } {
  const sign = totalInches < 0 ? -1 : 1;
  const abs = Math.abs(Math.round(totalInches));
  return { feet: sign * Math.floor(abs / INCHES_PER_FOOT), inches: abs % INCHES_PER_FOOT };
}

export function feetInchesToInches(feet: number, inches: number): number {
  return Math.round(feet * INCHES_PER_FOOT + inches);
}

/** `80 yd  ·  240 ft 0 in` — what a tape reads. */
export function formatTape(totalInches: number): string {
  const n = Math.round(totalInches);
  const yd = n / INCHES_PER_YARD;
  const { feet, inches } = splitFeetInches(n);
  const ydPart = Math.abs(n % INCHES_PER_YARD) < 1 ? `${Math.round(yd)} yd` : `${yd.toFixed(2)} yd`;
  return `${ydPart}  ·  ${feet} ft ${inches} in`;
}

export function formatYards(totalInches: number, digits = 2): string {
  const yd = inchesToYards(totalInches);
  const rounded = Math.round(yd * 10 ** digits) / 10 ** digits;
  return String(Number(rounded.toFixed(digits)));
}

/**
 * Surveyor's length: `80 yd`, `240 ft`, `240' 6"`, `10 yd 2 ft 3 in`.
 * A bare number is yards (soccer).
 */
export function parseLength(raw: string): number | null {
  const s = String(raw || "")
    .trim()
    .toLowerCase()
    .replace(/[×x].*$/, "")
    .replace(/,/g, "")
    .replace(/[′’]/g, "'")
    .replace(/[″”]/g, '"');
  if (!s) return null;
  let inches = 0;
  let matched = false;
  const re = /(\d+(?:\.\d+)?)\s*(yards?|yds?|yd|feet|foot|ft|'|inches|inch|ins?|")/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(s))) {
    matched = true;
    const n = Number(m[1]);
    const u = m[2];
    if (u.startsWith("yd") || u.startsWith("yard")) inches += n * INCHES_PER_YARD;
    else if (u === "'" || u.startsWith("ft") || u.startsWith("foot") || u.startsWith("feet")) inches += n * INCHES_PER_FOOT;
    else inches += n;
  }
  if (matched) return Math.round(inches);
  const just = Number(s);
  if (!Number.isFinite(just)) return null;
  return Math.round(just * INCHES_PER_YARD);
}

export function fullOutOfRange(lengthInches: number, widthInches: number): boolean {
  const long = inchesToYards(Math.max(lengthInches, widthInches));
  const short = inchesToYards(Math.min(lengthInches, widthInches));
  return long + 1e-6 < FULL_RANGE_YD.lengthMin || long - 1e-6 > FULL_RANGE_YD.lengthMax || short + 1e-6 < FULL_RANGE_YD.widthMin || short - 1e-6 > FULL_RANGE_YD.widthMax;
}

export function nearestClass(lengthInches: number, widthInches: number): NtssaClass {
  const long = Math.max(lengthInches, widthInches);
  const short = Math.min(lengthInches, widthInches);
  let best: NtssaClass = "small";
  let bestD = Infinity;
  for (const cls of Object.keys(NTSSA_DRAW) as NtssaClass[]) {
    const d = classSize(cls);
    const err = Math.abs(d.lengthInches - long) + Math.abs(d.widthInches - short);
    if (err < bestD) {
      bestD = err;
      best = cls;
    }
  }
  return best;
}

export function snapInches(value: number, pitchInches: number): number {
  if (!pitchInches || pitchInches <= 0) return value;
  return Math.round(value / pitchInches) * pitchInches;
}

export function normHeading(deg: number): number {
  let x = deg % 360;
  if (x < 0) x += 360;
  return x;
}
