/** Pure survey mutations. No DOM. */

import { enuFromPhoto, latLngToWorld } from "./geo";
import { checkIsAcross, headingOf, hypot, inchesPerPixel, photoCalibrated, photoWorldSize, pixelToWorld, rectFromDrag, worldToPixel } from "./geometry";
import { snapHeading, snapOverlayGeometry, snapPointGeometry } from "./snap";
import type { AssociationSurvey, NtssaClass, PhotoCheck, PhotoScale, Pt, RulerMeasure, SurveyOverlay, SurveyPhoto } from "./types";
import { classSize, nearestClass, normHeading, snapInches, yardsToInches } from "./units";

export type { NtssaClass } from "./units";

let seq = 0;

export function resetSurveyIds(n = 0): void {
  seq = n;
}

export function surveyId(prefix: string): string {
  seq += 1;
  return `${prefix}-${seq}`;
}

export function emptySurvey(): AssociationSurvey {
  return { photos: [], overlays: [], gridPitchInches: yardsToInches(1), snap: true };
}

export function cloneSurvey(s: AssociationSurvey): AssociationSurvey {
  return {
    photos: s.photos.map((p) => ({
      ...p,
      scale: p.scale ? { ...p.scale } : null,
      worldOriginInches: { ...p.worldOriginInches },
      baseline: p.baseline ? { ...p.baseline } : undefined,
      baselineSource: p.baselineSource,
      geodesy: p.geodesy ? { ...p.geodesy } : undefined,
      check: p.check ? { ...p.check } : undefined,
    })),
    overlays: s.overlays.map((o) => ({ ...o })),
    gridPitchInches: s.gridPitchInches,
    snap: s.snap,
    enu: s.enu ? { ...s.enu, originInches: { ...s.enu.originInches } } : undefined,
  };
}

export function addPhoto(survey: AssociationSurvey, photo: SurveyPhoto): AssociationSurvey {
  const next = cloneSurvey(survey);
  if (next.photos.length) {
    const last = next.photos[next.photos.length - 1];
    const size = photoWorldSize(last);
    photo = {
      ...photo,
      worldOriginInches: { x: last.worldOriginInches.x + size.w + yardsToInches(20), y: last.worldOriginInches.y },
    };
  }
  next.photos.push(photo);
  return next;
}

export function removePhoto(survey: AssociationSurvey, photoId: string): AssociationSurvey {
  const next = cloneSurvey(survey);
  next.photos = next.photos.filter((p) => p.id !== photoId);
  next.overlays = next.overlays.filter((o) => o.photoId !== photoId);
  return next;
}

export function setPhotoScale(survey: AssociationSurvey, photoId: string, scale: PhotoScale): AssociationSurvey {
  const next = cloneSurvey(survey);
  const photo = next.photos.find((p) => p.id === photoId);
  if (!photo) return next;
  const oldIpp = inchesPerPixel(photo) ?? 1;
  photo.scale = { ...scale };
  const newIpp = inchesPerPixel(photo) ?? oldIpp;
  const factor = newIpp / oldIpp;
  if (Math.abs(factor - 1) > 1e-9) {
    for (const o of next.overlays.filter((x) => x.photoId === photoId)) {
      o.cxInches = photo.worldOriginInches.x + (o.cxInches - photo.worldOriginInches.x) * factor;
      o.cyInches = photo.worldOriginInches.y + (o.cyInches - photo.worldOriginInches.y) * factor;
      o.lengthInches *= factor;
      o.widthInches *= factor;
    }
  }
  return next;
}

export function setPhotoCheck(survey: AssociationSurvey, photoId: string, check: PhotoCheck): AssociationSurvey {
  const next = cloneSurvey(survey);
  const photo = next.photos.find((p) => p.id === photoId);
  if (!photo) return next;
  const prior = { ...photo, check: undefined };
  const pixels = next.overlays.filter((o) => o.photoId === photoId).map((o) => ({
    id: o.id,
    pix: worldToPixel(prior, { x: o.cxInches, y: o.cyInches }),
  }));
  photo.check = { ...check };
  if (checkIsAcross(photo)) {
    for (const row of pixels) {
      const o = next.overlays.find((x) => x.id === row.id);
      if (!o) continue;
      const w = pixelToWorld(photo, row.pix.x, row.pix.y);
      o.cxInches = w.x;
      o.cyInches = w.y;
    }
  }
  return next;
}

export function placePhotosInEnu(survey: AssociationSurvey): AssociationSurvey {
  const next = cloneSurvey(survey);
  if (!next.enu) {
    const first = next.photos.find((p) => p.geodesy);
    const enu = first ? enuFromPhoto(first) : null;
    if (enu) next.enu = enu;
  }
  if (!next.enu) return next;
  for (const photo of next.photos) {
    const g = photo.geodesy;
    if (!g) continue;
    const desired = latLngToWorld(next.enu, g.lat, g.lng);
    const current = pixelToWorld(photo, g.px, g.py);
    const dx = desired.x - current.x;
    const dy = desired.y - current.y;
    if (hypot(dx, dy) < 0.5) continue;
    photo.worldOriginInches = { x: photo.worldOriginInches.x + dx, y: photo.worldOriginInches.y + dy };
    for (const o of next.overlays.filter((x) => x.photoId === photo.id)) {
      o.cxInches += dx;
      o.cyInches += dy;
    }
  }
  return next;
}

export function markCampusGcp(
  survey: AssociationSurvey,
  photoId: string,
  world: Pt,
  campus: { lat: number; lng: number },
  northDeg = 270,
): AssociationSurvey {
  const next = cloneSurvey(survey);
  const photo = next.photos.find((p) => p.id === photoId);
  if (!photo) return next;
  const pix = worldToPixel(photo, world);
  photo.geodesy = { lat: campus.lat, lng: campus.lng, px: pix.x, py: pix.y, northDeg };
  return placePhotosInEnu(next);
}

export function scalePhotoWidth(survey: AssociationSurvey, photoId: string, knownInches: number): AssociationSurvey {
  const photo = survey.photos.find((p) => p.id === photoId);
  if (!photo || knownInches <= 0) return survey;
  return setPhotoScale(survey, photoId, { ax: 0, ay: 0, bx: photo.pixelWidth, by: 0, knownInches });
}

export function snapPoint(survey: AssociationSurvey, p: Pt, excludeId?: string): Pt {
  if (!survey.snap) return p;
  const geom = snapPointGeometry(survey, p, excludeId);
  if (geom) return geom;
  return { x: snapInches(p.x, survey.gridPitchInches), y: snapInches(p.y, survey.gridPitchInches) };
}

export function snapOverlay(survey: AssociationSurvey, o: SurveyOverlay): SurveyOverlay {
  if (!survey.snap) return o;
  const geom = snapOverlayGeometry(survey, o);
  const placed = geom
    ? geom
    : {
        ...o,
        cxInches: snapInches(o.cxInches, survey.gridPitchInches),
        cyInches: snapInches(o.cyInches, survey.gridPitchInches),
      };
  return { ...placed, headingDeg: snapHeading(survey, placed) };
}

export function overlayFromDrag(survey: AssociationSurvey, photoId: string, a: Pt, b: Pt, defaults: Partial<SurveyOverlay> = {}): SurveyOverlay {
  const rect = rectFromDrag(a, b);
  const cls = (defaults.ntssaClass as NtssaClass | undefined) || nearestClass(rect.lengthInches, rect.widthInches);
  let o: SurveyOverlay = {
    id: surveyId("field"),
    photoId,
    fieldName: defaults.fieldName || "",
    ntssaClass: cls,
    campus: defaults.campus || "",
    parking: defaults.parking || "",
    availableRaw: defaults.availableRaw || "Saturday 8:00-18:00",
    cxInches: rect.cx,
    cyInches: rect.cy,
    headingDeg: rect.headingDeg,
    lengthInches: rect.lengthInches,
    widthInches: rect.widthInches,
    source: "drawn",
  };
  o = snapOverlay(survey, o);
  return o;
}

export function stampClass(survey: AssociationSurvey, photoId: string, at: Pt, cls: NtssaClass, defaults: Partial<SurveyOverlay> = {}): SurveyOverlay {
  const size = classSize(cls);
  const p = snapPoint(survey, at);
  return snapOverlay(survey, {
    id: surveyId("field"),
    photoId,
    fieldName: defaults.fieldName || "",
    ntssaClass: cls,
    campus: defaults.campus || "",
    parking: defaults.parking || "",
    availableRaw: defaults.availableRaw || "Saturday 8:00-18:00",
    cxInches: p.x,
    cyInches: p.y,
    headingDeg: defaults.headingDeg ?? 90,
    lengthInches: size.lengthInches,
    widthInches: size.widthInches,
    source: "drawn",
  });
}

export function addOverlay(survey: AssociationSurvey, overlay: SurveyOverlay): AssociationSurvey {
  const next = cloneSurvey(survey);
  next.overlays.push(overlay);
  return next;
}

export function updateOverlay(survey: AssociationSurvey, id: string, patch: Partial<SurveyOverlay>): AssociationSurvey {
  const next = cloneSurvey(survey);
  const o = next.overlays.find((x) => x.id === id);
  if (o) Object.assign(o, patch);
  return next;
}

export function deleteOverlay(survey: AssociationSurvey, id: string): AssociationSurvey {
  const next = cloneSurvey(survey);
  next.overlays = next.overlays.filter((o) => o.id !== id);
  return next;
}

export function moveOverlay(survey: AssociationSurvey, id: string, dx: number, dy: number): AssociationSurvey {
  const next = cloneSurvey(survey);
  const o = next.overlays.find((x) => x.id === id);
  if (!o) return next;
  o.cxInches += dx;
  o.cyInches += dy;
  Object.assign(o, snapOverlay(next, o));
  return next;
}

export function rotateOverlay(survey: AssociationSurvey, id: string, headingDeg: number): AssociationSurvey {
  return updateOverlay(survey, id, { headingDeg: normHeading(headingDeg) });
}

export function fitNtssa(survey: AssociationSurvey, id: string): AssociationSurvey {
  const o = survey.overlays.find((x) => x.id === id);
  if (!o) return survey;
  const size = classSize(o.ntssaClass);
  return updateOverlay(survey, id, { lengthInches: size.lengthInches, widthInches: size.widthInches });
}

export function cloneOverlay(survey: AssociationSurvey, id: string): AssociationSurvey {
  const src = survey.overlays.find((x) => x.id === id);
  if (!src) return survey;
  const pitch = survey.gridPitchInches || yardsToInches(5);
  const copy: SurveyOverlay = {
    ...src,
    id: surveyId("field"),
    fieldName: src.fieldName ? `${src.fieldName} copy` : "",
    cxInches: src.cxInches + src.widthInches + pitch,
    source: "cloned",
  };
  return addOverlay(survey, snapOverlay(survey, copy));
}

export function copyPayload(o: SurveyOverlay): SurveyOverlay {
  return { ...o, id: "", source: "pasted" };
}

export function pasteOverlay(survey: AssociationSurvey, payload: SurveyOverlay, photoId: string, at?: Pt): AssociationSurvey {
  const pitch = survey.gridPitchInches || yardsToInches(5);
  const o: SurveyOverlay = {
    ...payload,
    id: surveyId("field"),
    photoId,
    fieldName: payload.fieldName ? `${payload.fieldName} copy` : "",
    cxInches: at?.x ?? payload.cxInches + payload.widthInches + pitch,
    cyInches: at?.y ?? payload.cyInches,
    source: "pasted",
  };
  return addOverlay(survey, snapOverlay(survey, o));
}

export function measure(a: Pt, b: Pt): RulerMeasure {
  return { a, b, inches: hypot(b.x - a.x, b.y - a.y), headingDeg: headingOf(a, b) };
}

export function worldFromEventPhoto(photo: SurveyPhoto, px: number, py: number): Pt {
  return pixelToWorld(photo, px, py);
}

export function photoById(survey: AssociationSurvey, id: string | undefined): SurveyPhoto | undefined {
  return survey.photos.find((p) => p.id === id);
}

export { photoCalibrated, pixelToWorld };
