/**
 * Genetic search beside Z3. Starts from a proposed sitting the moment
 * Plan is pressed; mutates/crosses; fitness is household/whistle burns
 * (Sims) plus Z3-style cost and diversity. A Z3 sitting is an elite
 * injected into the pool when it lands — never the only game in town.
 */

import { playingSaturdays, weeks } from "./calendar";
import { formatClockShort, formatLong, formatSheetDate, formatSheetTime, parseClock } from "./dates";
import { scoreSeasonDiversity } from "./diversity";
import { findField, scoreSeasonZ3, stampSeasonScores } from "./season-score";
import { applySimsJudgment, judgeSeason } from "./sims";
import { playTimesOverlap, peopleOnGame } from "./schedule-sheet";
import { norm, teamLabel, type Configuration, type League, type PlacedGame } from "./model";
import { seedSeason } from "./solver";

export const TOP_PROPOSALS = 5;
const POP = 8;
export const MIN_GEN = 8;
/** Stop once best fitness has not moved for this many generations (after MIN_GEN). */
export const STALL_GEN = 4;
const EXTRA_AFTER_Z3 = 4;
const MAX_GEN = 200;

export type GenomeOrigin = "ga" | "z3";

export interface DayCell {
  dateIso: string;
  score: number;
  tightness: number;
  games: PlacedGame[];
}

export interface Genome {
  id: string;
  origin: GenomeOrigin;
  generation: number;
  games: PlacedGame[];
  simsScore: number;
  simsLegal: boolean;
  simsFeasible: boolean;
  z3Score: number;
  z3Cost: number;
  diversityScore: number;
  days: DayCell[];
  fitness: number;
}

export interface GaProgress {
  generation: number;
  bestSims: number;
  best: Genome;
  top: Genome[];
  z3Joined: boolean;
  converged: boolean;
  history: number[];
  stallGens: number;
}

export interface GaResult extends GaProgress {
  z3Config?: Configuration;
  z3Error?: Error;
}

export interface RunGaOpts {
  z3?: Promise<Configuration>;
  onProgress: (p: GaProgress) => void;
  maxGenerations?: number;
  minGenerations?: number;
  seed?: number;
}

function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function yieldUi(): Promise<void> {
  return new Promise((resolve) => {
    if (typeof requestAnimationFrame === "function") {
      requestAnimationFrame(() => setTimeout(resolve, 0));
    } else {
      setTimeout(resolve, 0);
    }
  });
}

export function cloneGames(games: PlacedGame[]): PlacedGame[] {
  return games.map((g) => ({ ...g, assistants: [...g.assistants], notes: [...g.notes] }));
}

export function fingerprint(games: PlacedGame[]): string {
  return games
    .map((g) => `${g.dateIso}|${g.kickoff}|${g.field}|${g.campus}|${g.home}|${g.away}`)
    .sort()
    .join(";");
}

function clamp(n: number, lo = 0, hi = 100): number {
  return Math.max(lo, Math.min(hi, n));
}

function clocksOverlap(a: PlacedGame, b: PlacedGame): boolean {
  if (a.dateIso !== b.dateIso) return false;
  const a0 = parseClock(a.warmupStart) ?? (parseClock(a.kickoff) ?? 0) - 15;
  const a1 = parseClock(a.vacate) ?? (parseClock(a.end) ?? 0);
  const b0 = parseClock(b.warmupStart) ?? (parseClock(b.kickoff) ?? 0) - 15;
  const b1 = parseClock(b.vacate) ?? (parseClock(b.end) ?? 0);
  return a0 < b1 && b0 < a1;
}

function seasonDates(league: League, games: PlacedGame[]): string[] {
  const sats = playingSaturdays(league).filter((d) => !weeks(league).find((w) => w.label === d && w.kind === "bye"));
  const extra = games.map((g) => g.dateIso);
  return [...new Set([...sats, ...extra])].sort();
}

/** Fast household/whistle tightness so gen 0 can paint before a full Sims walk. */
export function scoreCheap(league: League, games: PlacedGame[]): { score: number; days: DayCell[] } {
  const dates = seasonDates(league, games);
  const days: DayCell[] = dates.map((dateIso) => {
    const on = games.filter((g) => g.dateIso === dateIso);
    let penalty = 0;
    for (let i = 0; i < on.length; i++) {
      if (!on[i].center && !league.season.proceedWithoutStaff) penalty += 18;
      for (let j = i + 1; j < on.length; j++) {
        if (on[i].field === on[j].field && on[i].campus === on[j].campus && clocksOverlap(on[i], on[j])) {
          penalty += 22;
        }
        if (on[i].center && on[i].center === on[j].center && playTimesOverlap(on[i], on[j])) penalty += 20;
        const shared = peopleOnGame(league, on[i]).filter((n) =>
          peopleOnGame(league, on[j]).some((m) => norm(m) === norm(n)),
        );
        if (shared.length && playTimesOverlap(on[i], on[j])) penalty += 24;
      }
    }
    for (const f of league.families) {
      if (f.children.length < 2) continue;
      const stops: PlacedGame[] = [];
      for (const c of f.children) {
        const t = league.teams.find((x) => x.name === c.team && x.bracket === c.bracket);
        const label = t ? teamLabel(t) : `${c.bracket} ${c.team}`;
        const g = on.find((x) => x.home === label || x.away === label);
        if (g) stops.push(g);
      }
      for (let i = 0; i < stops.length; i++) {
        for (let j = i + 1; j < stops.length; j++) {
          if (!clocksOverlap(stops[i], stops[j])) continue;
          penalty += norm(stops[i].campus) === norm(stops[j].campus) ? 6 : 16;
        }
      }
    }
    const score = clamp(100 - penalty);
    return { dateIso, score, tightness: 1 - score / 100, games: on };
  });
  const score = days.length ? Math.round(days.reduce((n, d) => n + d.score, 0) / days.length) : 0;
  return { score, days };
}

function retimed(g: PlacedGame, kick: number): PlacedGame {
  const cur = parseClock(g.kickoff) ?? kick;
  const length = (parseClock(g.end) ?? cur + 50) - cur;
  const end = kick + Math.max(20, length);
  return {
    ...g,
    kickoff: formatClockShort(kick),
    end: formatClockShort(end),
    warmupStart: formatClockShort(kick - 15),
    vacate: formatClockShort(end + 10), // restamp from age clock after mutate
  };
}

function fieldAllows(league: League, game: PlacedGame, field: League["fields"][number], kick: number): boolean {
  const ag = league.ageGroups.find((a) => norm(a.name) === norm(game.ageGroup));
  if (ag && !ag.fieldClasses.some((c) => norm(c) === norm(field.type))) return false;
  const day = ["sunday", "monday", "tuesday", "wednesday", "thursday", "friday", "saturday"][
    new Date(`${game.dateIso}T00:00:00Z`).getUTCDay()
  ];
  const win = field.windows.find((w) => w.day === day);
  const length = (parseClock(game.end) ?? kick + 50) - (parseClock(game.kickoff) ?? kick);
  const vacate = kick + Math.max(20, length) + 10;
  if (field.windows.length && !win) return false;
  if (win && (kick < win.startMinutes || vacate > win.endMinutes + 5)) return false;
  return true;
}

function swapSlots(a: PlacedGame, b: PlacedGame): void {
  const keys = [
    "dateIso",
    "weekIso",
    "kickoff",
    "end",
    "warmupStart",
    "vacate",
    "field",
    "campus",
    "parking",
    "center",
  ] as const;
  for (const k of keys) {
    const tmp = a[k];
    Object.assign(a, { [k]: b[k] });
    Object.assign(b, { [k]: tmp });
  }
}

export function mutateSeason(league: League, games: PlacedGame[], rng: () => number): PlacedGame[] {
  const next = cloneGames(games);
  if (next.length < 2) return next;
  const roll = rng();
  if (roll < 0.55) {
    const a = next[Math.floor(rng() * next.length)];
    const same = next.filter((g) => g.dateIso === a.dateIso && g.id !== a.id);
    const b = same[Math.floor(rng() * Math.max(1, same.length))] || next[Math.floor(rng() * next.length)];
    if (a.id !== b.id) swapSlots(a, b);
    return next;
  }
  if (roll < 0.85) {
    const g = next[Math.floor(rng() * next.length)];
    const kicks = [8 * 60, 8 * 60 + 30, 9 * 60, 9 * 60 + 30, 10 * 60, 10 * 60 + 30, 11 * 60, 12 * 60, 13 * 60, 14 * 60];
    const field = findField(league, g.field);
    const shuffled = kicks.filter((k) => k !== (parseClock(g.kickoff) ?? -1)).sort(() => rng() - 0.5);
    const kick = shuffled.find((k) => (field ? fieldAllows(league, g, field, k) : true)) || shuffled[0];
    if (kick != null) {
      const i = next.findIndex((x) => x.id === g.id);
      next[i] = retimed(g, kick);
    }
    return next;
  }
  const g = next[Math.floor(rng() * next.length)];
  const ag = league.ageGroups.find((a) => norm(a.name) === norm(g.ageGroup));
  const legal = league.fields.filter((f) => {
    if (ag && !ag.fieldClasses.some((c) => norm(c) === norm(f.type))) return false;
    return fieldAllows(league, g, f, parseClock(g.kickoff) ?? 10 * 60);
  });
  if (legal.length) {
    const f = legal[Math.floor(rng() * legal.length)];
    const m = f.name.match(/Field\s+([A-Z])/i);
    g.field = /stadium/i.test(f.name) ? f.name : m ? `Field ${m[1].toUpperCase()}` : f.name;
    g.campus = f.campus;
    g.parking = f.parking;
  }
  return next;
}

export function crossover(a: PlacedGame[], b: PlacedGame[], rng: () => number): PlacedGame[] {
  const dates = [...new Set([...a, ...b].map((g) => g.dateIso))].sort();
  const out: PlacedGame[] = [];
  const cut = dates[Math.floor(rng() * Math.max(1, dates.length))] || dates[0];
  for (const d of dates) {
    const src = d < cut ? a : b;
    const other = d < cut ? b : a;
    const take = src.filter((g) => g.dateIso === d);
    out.push(...cloneGames(take.length ? take : other.filter((g) => g.dateIso === d)));
  }
  return out.map((g, i) => ({ ...g, id: `g${i + 1}` }));
}

let genomeSeq = 0;

export function scoreGenome(
  league: League,
  games: PlacedGame[],
  origin: GenomeOrigin,
  generation: number,
  fullSims = false,
): Genome {
  const cheap = scoreCheap(league, games);
  const z3 = scoreSeasonZ3(league, games);
  const div = scoreSeasonDiversity(league, games);
  let simsScore = cheap.score;
  let simsLegal = cheap.score >= 50;
  let simsFeasible = cheap.score >= 70;
  let days = cheap.days;
  if (fullSims) {
    const judged = judgeSeason(league, { games } as Configuration);
    simsScore = judged.days.length
      ? Math.round(judged.days.reduce((n, d) => n + d.score.score, 0) / judged.days.length)
      : cheap.score;
    simsLegal = judged.legal;
    simsFeasible = judged.feasible;
    days = cheap.days.map((c) => {
      const demo = judged.days.find((d) => d.dateIso === c.dateIso);
      if (!demo) return c;
      const score = demo.score.score;
      return { ...c, score, tightness: 1 - score / 100 };
    });
  }
  const fitness = simsScore * 100 + div.score * 10 + z3.score / 20 + (origin === "z3" ? 40 : 0);
  return {
    id: `gn-${origin}-${generation}-${++genomeSeq}`,
    origin,
    generation,
    games: cloneGames(games),
    simsScore,
    simsLegal,
    simsFeasible,
    z3Score: z3.score,
    z3Cost: z3.cost,
    diversityScore: div.score,
    days,
    fitness,
  };
}

function rank(pop: Genome[]): Genome[] {
  return [...pop].sort((a, b) => b.fitness - a.fitness || b.simsScore - a.simsScore || b.z3Score - a.z3Score);
}

export function topUnique(pop: Genome[], n = TOP_PROPOSALS): Genome[] {
  const out: Genome[] = [];
  const seen = new Set<string>();
  const z3 = rank(pop).find((g) => g.origin === "z3");
  if (z3) {
    out.push(z3);
    seen.add(fingerprint(z3.games));
  }
  for (const g of rank(pop)) {
    const fp = fingerprint(g.games);
    if (seen.has(fp)) continue;
    seen.add(fp);
    out.push(g);
    if (out.length >= n) break;
  }
  return out;
}

function snapshot(generation: number, pop: Genome[], z3Joined: boolean): GaProgress {
  const ranked = rank(pop);
  const top = topUnique(ranked);
  const best = top[0] || ranked[0];
  return {
    generation,
    bestSims: best?.simsScore ?? 0,
    best,
    top,
    z3Joined,
    converged: false,
    history: [],
    stallGens: 0,
  };
}

export async function runSeasonGa(league: League, opts: RunGaOpts): Promise<GaResult> {
  const rng = mulberry32(opts.seed ?? 2026);
  const minGen = opts.minGenerations ?? MIN_GEN;
  const maxGen = opts.maxGenerations ?? MAX_GEN;
  const seeded = seedSeason(league);
  let pop: Genome[] = [scoreGenome(league, seeded.games, "ga", 0, false)];
  while (pop.length < POP) {
    pop.push(scoreGenome(league, mutateSeason(league, pop[0].games, rng), "ga", 0, false));
  }
  let generation = 0;
  let z3Joined = false;
  let z3Config: Configuration | undefined;
  let z3Error: Error | undefined;
  let z3Done = !opts.z3;
  if (opts.z3) {
    opts.z3.then(
      (cfg) => {
        z3Config = cfg;
        z3Done = true;
      },
      (err) => {
        z3Error = err instanceof Error ? err : new Error(String(err));
        z3Done = true;
      },
    );
  }

  let history: number[] = [];
  let bestFit = Number.NEGATIVE_INFINITY;
  let stall = 0;
  let converged = false;

  const emit = () => {
    const snap = snapshot(generation, pop, z3Joined);
    const fit = snap.best?.fitness ?? 0;
    history = [...history, snap.bestSims];
    if (fit > bestFit) {
      bestFit = fit;
      stall = 0;
    } else {
      stall += 1;
    }
    converged = generation >= minGen && stall >= STALL_GEN;
    opts.onProgress({ ...snap, converged, history, stallGens: stall });
  };
  emit();
  await yieldUi();

  const tryInjectZ3 = () => {
    if (z3Joined || !z3Config) return;
    pop.push(scoreGenome(league, z3Config.games, "z3", generation, true));
    z3Joined = true;
    stall = 0;
  };

  pop[0] = scoreGenome(league, pop[0].games, "ga", 0, true);
  emit();
  await yieldUi();

  const z3Ready = () => !opts.z3 || z3Joined || !!z3Error;

  while (generation < maxGen) {
    tryInjectZ3();
    generation += 1;
    const elites = rank(pop).slice(0, 2);
    const z3Elite = pop.find((g) => g.origin === "z3");
    if (z3Elite && !elites.some((e) => e.id === z3Elite.id)) elites.push(z3Elite);
    const children: Genome[] = [];
    const mom = elites[0] || pop[0];
    const dad = elites[1] || pop[Math.floor(rng() * pop.length)] || mom;
    children.push(scoreGenome(league, crossover(mom.games, dad.games, rng), "ga", generation, false));
    children.push(scoreGenome(league, mutateSeason(league, mom.games, rng), mom.origin, generation, false));
    children.push(scoreGenome(league, mutateSeason(league, dad.games, rng), "ga", generation, false));
    const next = rank([...elites, ...children, ...pop]);
    const keptZ3 = next.find((g) => g.origin === "z3");
    pop = next.slice(0, POP);
    if (keptZ3 && !pop.some((g) => g.origin === "z3")) pop[pop.length - 1] = keptZ3;
    pop[0] = scoreGenome(league, pop[0].games, pop[0].origin, generation, true);
    emit();
    await yieldUi();
    if (z3Done && !z3Joined) tryInjectZ3();
    if (generation >= minGen && z3Ready() && converged) break;
  }

  while (!z3Done) await yieldUi();
  tryInjectZ3();
  if (z3Joined && !converged) {
    for (let i = 0; i < EXTRA_AFTER_Z3 && generation < maxGen && !converged; i++) {
      generation += 1;
      const best = rank(pop)[0];
      pop.push(scoreGenome(league, mutateSeason(league, best.games, rng), best.origin, generation, false));
      const ranked = rank(pop);
      const keepZ3 = ranked.find((g) => g.origin === "z3");
      pop = ranked.slice(0, POP);
      if (keepZ3 && !pop.some((g) => g.origin === "z3")) pop[pop.length - 1] = keepZ3;
      pop[0] = scoreGenome(league, pop[0].games, pop[0].origin, generation, true);
      emit();
      await yieldUi();
    }
  }

  const finalSnap = snapshot(generation, pop, z3Joined);
  for (let guard = 0; finalSnap.top.length < TOP_PROPOSALS && pop[0] && guard < 24; guard++) {
    const extra = scoreGenome(league, mutateSeason(league, pop[0].games, rng), "ga", generation, false);
    pop.push(extra);
    finalSnap.top = topUnique(pop);
  }
  const final: GaProgress = { ...finalSnap, converged, history, stallGens: stall };
  opts.onProgress(final);
  return { ...final, z3Config, z3Error };
}

export const MINIMAP_CAPTION = "Green is easier — fewer household and whistle burns that day.";

function heatFill(tightness: number): string {
  const t = clamp(tightness);
  const h = Math.round(118 - t * 118);
  const s = Math.round(46 + t * 32);
  const l = Math.round(72 - t * 24);
  return `hsl(${h} ${s}% ${l}%)`;
}

/** Best-Sims history as a small line. Settled when the search stopped on its own. */
export function sparklineHtml(history: number[], opts: { settled?: boolean } = {}): string {
  const w = 280;
  const h = 48;
  const n = history.length;
  const settled = opts.settled ? "yes" : "no";
  if (!n) {
    return `<div class="ga-spark" data-ga-spark data-ga-spark-n="0" data-settled="${settled}"></div>`;
  }
  const lo = Math.min(...history, 0);
  const hi = Math.max(...history, lo + 1);
  const span = hi - lo || 1;
  const pts = history
    .map((v, i) => {
      const x = n === 1 ? w / 2 : (i / (n - 1)) * w;
      const y = h - 6 - ((v - lo) / span) * (h - 12);
      return `${x.toFixed(1)},${y.toFixed(1)}`;
    })
    .join(" ");
  return `<div class="ga-spark" data-ga-spark data-ga-spark-n="${n}" data-settled="${settled}">
    <svg viewBox="0 0 ${w} ${h}" aria-hidden="true"><polyline data-ga-spark-line points="${pts}" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linejoin="round" stroke-linecap="round"/></svg>
  </div>`;
}

export function minimapHtml(
  cells: DayCell[],
  opts: { pinned?: string; hover?: string; live?: boolean } = {},
): string {
  const open = opts.pinned || opts.hover || "";
  const bits = cells
    .map((c) => {
      const on = open === c.dateIso ? "yes" : "no";
      const pin = opts.pinned === c.dateIso ? "yes" : "no";
      return `<button type="button" class="minimap-day" data-minimap-day="${c.dateIso}" data-minimap-tightness="${Math.round(c.tightness * 100)}" data-day-open="${on}" data-day-pin="${pin}" style="background:${heatFill(c.tightness)}" title="${formatSheetDate(c.dateIso)} · Sims ${c.score}">
        <span class="minimap-date">${formatSheetDate(c.dateIso)}</span>
        <span class="minimap-n">${c.games.length}</span>
      </button>`;
    })
    .join("");
  return `<div class="minimap" data-season-minimap data-minimap-heat="green-rust" data-minimap-live="${opts.live ? "yes" : "no"}">${bits || `<p class="meta">no days yet</p>`}</div>
    <p class="minimap-caption" data-minimap-caption>${MINIMAP_CAPTION}</p>`;
}

export function dayEntryHtml(league: League, cell: DayCell | undefined, pinned: boolean): string {
  if (!cell) return `<div data-day-entry hidden></div>`;
  const rows = [...cell.games]
    .sort((a, b) => (parseClock(a.kickoff) ?? 0) - (parseClock(b.kickoff) ?? 0))
    .map(
      (g) =>
        `<li data-day-game="${g.id}"><span>${formatSheetTime(g.kickoff)}</span> ${g.home} vs ${g.away} · ${g.field} · ${g.campus}${g.center ? ` · ${g.center}` : ""}</li>`,
    );
  return `<div data-day-entry data-day="${cell.dateIso}" data-day-pinned="${pinned ? "yes" : "no"}">
    <p data-day-heading>${formatLong(cell.dateIso)} · score ${cell.score}</p>
    <ul data-day-games>${rows.join("") || "<li>no games</li>"}</ul>
    ${pinned ? `<button type="button" class="link" data-action="unpin-day">Unpin this day</button>` : `<p class="meta">Click the day to pin it open.</p>`}
  </div>`;
}

export function proposalsHtml(top: Genome[], active: number): string {
  const chips = top
    .map((g, i) => {
      const n = i + 1;
      const tag = g.origin === "z3" ? "Z3" : "GA";
      return `<button type="button" class="chip" data-proposal="${n}" data-proposal-origin="${g.origin}" aria-current="${i === active ? "true" : "false"}">${n} · ${tag} · Sims ${g.simsScore}</button>`;
    })
    .join("");
  const g = top[active] || top[0];
  const breakdown = g
    ? `<p data-proposal-breakdown>Sims ${g.simsScore}${g.simsLegal ? "" : " (not legal)"} · Z3-style ${g.z3Score} · Diversity ${g.diversityScore}</p>`
    : "";
  return `<div class="proposals" data-proposals data-active="${active + 1}" data-count="${top.length}">
    <p class="meta">Top ${Math.min(TOP_PROPOSALS, top.length)} proposals — cycle to compare</p>
    <nav data-proposal-cycle>${chips}</nav>
    ${breakdown}
  </div>`;
}

export function genomeToConfiguration(
  league: League,
  g: Genome,
  name: string,
  id: string,
  z3Meta?: Pick<Configuration, "engine" | "z3Probe" | "z3Verdict" | "folding" | "diagnostics" | "scores" | "hardHeld">,
): Configuration {
  const cfg: Configuration = {
    id,
    name,
    createdAt: "just now",
    games: cloneGames(g.games),
    scores:
      g.origin === "z3"
        ? [...(z3Meta?.scores || [])]
        : [{ key: "engine", text: "Genetic search — Sims fitness; Z3 elites join the pool when they land" }],
    hardHeld: z3Meta?.hardHeld ?? g.simsLegal,
    diagnostics: [...(z3Meta?.diagnostics || [])],
    engine: z3Meta?.engine,
    z3Probe: z3Meta?.z3Probe,
    z3Verdict: z3Meta?.z3Verdict,
    folding: z3Meta?.folding,
  };
  stampSeasonScores(league, cfg);
  applySimsJudgment(league, cfg);
  return cfg;
}

export { seedSeason };
