/** Rotated rectangles in world inches. */

import type { PixelBaseline, Pt, SurveyOverlay, SurveyPhoto } from "./types";
import { normHeading } from "./units";

export function hypot(dx: number, dy: number): number {
  return Math.sqrt(dx * dx + dy * dy);
}

export function headingOf(a: Pt, b: Pt): number {
  return normHeading((Math.atan2(b.y - a.y, b.x - a.x) * 180) / Math.PI);
}

export function inchesPerPixel(photo: SurveyPhoto): number | null {
  const s = photo.scale;
  if (!s || s.knownInches <= 0) return null;
  const d = hypot(s.bx - s.ax, s.by - s.ay);
  if (d < 1e-6) return null;
  return s.knownInches / d;
}

export function photoCalibrated(photo: SurveyPhoto): boolean {
  return inchesPerPixel(photo) != null;
}

/** True when the check line is ≥60° from the scale baseline — it can set the across scale. */
export function checkIsAcross(photo: SurveyPhoto): boolean {
  const s = photo.scale;
  const k = photo.check;
  if (!s || !k || k.knownInches <= 0) return false;
  const sx = s.bx - s.ax;
  const sy = s.by - s.ay;
  const sl = hypot(sx, sy);
  const cx = k.bx - k.ax;
  const cy = k.by - k.ay;
  const cl = hypot(cx, cy);
  if (sl < 1e-6 || cl < 1e-6) return false;
  const sin = Math.abs(sx * cy - sy * cx) / (sl * cl);
  return sin >= Math.sin((60 * Math.PI) / 180);
}

/** Affine-free map: isotropic, or along/across scales from a perpendicular check. */
export function photoMap(photo: SurveyPhoto): { a: number; b: number; c: number; d: number; e: number; f: number } {
  const ipp = inchesPerPixel(photo) ?? 1;
  let a = ipp;
  let b = 0;
  let c = 0;
  let d = ipp;
  const s = photo.scale;
  const k = photo.check;
  if (s && k && checkIsAcross(photo)) {
    const sx = s.bx - s.ax;
    const sy = s.by - s.ay;
    const sl = hypot(sx, sy) || 1;
    const ux = sx / sl;
    const uy = sy / sl;
    const vx = uy;
    const vy = -ux;
    const alongIpp = s.knownInches / sl;
    const cx = k.bx - k.ax;
    const cy = k.by - k.ay;
    const acrossPx = cx * vx + cy * vy;
    const alongPx = cx * ux + cy * uy;
    const alongWorld = alongPx * alongIpp;
    const rest = k.knownInches * k.knownInches - alongWorld * alongWorld;
    const acrossIpp = rest > 0 && Math.abs(acrossPx) > 1e-6 ? Math.sqrt(rest) / Math.abs(acrossPx) : alongIpp;
    const rd00 = ux * alongIpp;
    const rd01 = vx * acrossIpp;
    const rd10 = uy * alongIpp;
    const rd11 = vy * acrossIpp;
    a = rd00 * ux + rd01 * vx;
    c = rd00 * uy + rd01 * vy;
    b = rd10 * ux + rd11 * vx;
    d = rd10 * uy + rd11 * vy;
  }
  const rad = (photo.worldRotationDeg * Math.PI) / 180;
  const cos = Math.cos(rad);
  const sin = Math.sin(rad);
  return {
    a: cos * a - sin * b,
    b: sin * a + cos * b,
    c: cos * c - sin * d,
    d: sin * c + cos * d,
    e: photo.worldOriginInches.x,
    f: photo.worldOriginInches.y,
  };
}

export function photoWorldSize(photo: SurveyPhoto): { w: number; h: number; ipp: number } {
  const p0 = pixelToWorld(photo, 0, 0);
  const p1 = pixelToWorld(photo, photo.pixelWidth, 0);
  const p2 = pixelToWorld(photo, photo.pixelWidth, photo.pixelHeight);
  const p3 = pixelToWorld(photo, 0, photo.pixelHeight);
  const xs = [p0.x, p1.x, p2.x, p3.x];
  const ys = [p0.y, p1.y, p2.y, p3.y];
  return {
    w: Math.max(...xs) - Math.min(...xs),
    h: Math.max(...ys) - Math.min(...ys),
    ipp: inchesPerPixel(photo) ?? 1,
  };
}

export function pixelToWorld(photo: SurveyPhoto, px: number, py: number): Pt {
  const m = photoMap(photo);
  return { x: m.a * px + m.c * py + m.e, y: m.b * px + m.d * py + m.f };
}

/** Photo-normalized (0–1) → world inches. Fractions survive JPEG resize. */
export function worldFromNorm(photo: SurveyPhoto, u: number, v: number): Pt {
  return pixelToWorld(photo, u * photo.pixelWidth, v * photo.pixelHeight);
}

export function normFromWorld(photo: SurveyPhoto, p: Pt): Pt {
  const px = worldToPixel(photo, p);
  return { x: px.x / photo.pixelWidth, y: px.y / photo.pixelHeight };
}

export function worldToPixel(photo: SurveyPhoto, world: Pt): Pt {
  const m = photoMap(photo);
  const dx = world.x - m.e;
  const dy = world.y - m.f;
  const det = m.a * m.d - m.c * m.b || 1;
  return { x: (m.d * dx - m.c * dy) / det, y: (-m.b * dx + m.a * dy) / det };
}

export function fieldCorners(o: SurveyOverlay): Pt[] {
  const l = o.lengthInches / 2;
  const w = o.widthInches / 2;
  const rad = (o.headingDeg * Math.PI) / 180;
  const c = Math.cos(rad);
  const s = Math.sin(rad);
  const local: Pt[] = [
    { x: -l, y: -w },
    { x: l, y: -w },
    { x: l, y: w },
    { x: -l, y: w },
  ];
  return local.map((p) => ({
    x: o.cxInches + p.x * c - p.y * s,
    y: o.cyInches + p.x * s + p.y * c,
  }));
}

export function fieldRotateHandle(o: SurveyOverlay): Pt {
  const rad = (o.headingDeg * Math.PI) / 180;
  const reach = o.lengthInches / 2;
  return {
    x: o.cxInches + reach * Math.cos(rad),
    y: o.cyInches + reach * Math.sin(rad),
  };
}

export function pointInOverlay(o: SurveyOverlay, p: Pt): boolean {
  const rad = (-o.headingDeg * Math.PI) / 180;
  const c = Math.cos(rad);
  const s = Math.sin(rad);
  const dx = p.x - o.cxInches;
  const dy = p.y - o.cyInches;
  const lx = dx * c - dy * s;
  const ly = dx * s + dy * c;
  return Math.abs(lx) <= o.lengthInches / 2 + 1e-6 && Math.abs(ly) <= o.widthInches / 2 + 1e-6;
}

function projectionsOverlap(a: number[], b: number[]): boolean {
  return Math.max(...a) >= Math.min(...b) - 1e-6 && Math.max(...b) >= Math.min(...a) - 1e-6;
}

function axesOf(corners: Pt[]): Pt[] {
  const e0 = { x: corners[1].x - corners[0].x, y: corners[1].y - corners[0].y };
  const e1 = { x: corners[3].x - corners[0].x, y: corners[3].y - corners[0].y };
  return [
    { x: -e0.y, y: e0.x },
    { x: -e1.y, y: e1.x },
  ];
}

function project(corners: Pt[], axis: Pt): number[] {
  const mag = hypot(axis.x, axis.y) || 1;
  const nx = axis.x / mag;
  const ny = axis.y / mag;
  return corners.map((p) => p.x * nx + p.y * ny);
}

export function overlaysOverlap(a: SurveyOverlay, b: SurveyOverlay): boolean {
  const ca = fieldCorners(a);
  const cb = fieldCorners(b);
  for (const axis of [...axesOf(ca), ...axesOf(cb)]) {
    if (!projectionsOverlap(project(ca, axis), project(cb, axis))) return false;
  }
  return true;
}

export function overlayOutsidePhoto(o: SurveyOverlay, photo: SurveyPhoto): boolean {
  const { w, h } = photoWorldSize(photo);
  const origin = photo.worldOriginInches;
  return fieldCorners(o).some((p) => p.x < origin.x - 1 || p.y < origin.y - 1 || p.x > origin.x + w + 1 || p.y > origin.y + h + 1);
}

export function rectFromDrag(a: Pt, b: Pt): { cx: number; cy: number; lengthInches: number; widthInches: number; headingDeg: number } {
  const dx = Math.abs(b.x - a.x);
  const dy = Math.abs(b.y - a.y);
  const cx = (a.x + b.x) / 2;
  const cy = (a.y + b.y) / 2;
  if (dx >= dy) return { cx, cy, lengthInches: Math.max(dx, 1), widthInches: Math.max(dy, 1), headingDeg: 0 };
  return { cx, cy, lengthInches: Math.max(dy, 1), widthInches: Math.max(dx, 1), headingDeg: 90 };
}

export function pointsToSvg(pts: Pt[]): string {
  return pts.map((p) => `${p.x},${p.y}`).join(" ");
}

export function headingUnit(deg: number): Pt {
  const r = (deg * Math.PI) / 180;
  return { x: Math.cos(r), y: Math.sin(r) };
}

/** Photo-width shortcut — not a 12U touchline. */
export function isFullWidthScale(photo: SurveyPhoto): boolean {
  const s = photo.scale;
  if (!s) return false;
  return Math.abs(s.ax) < 1 && Math.abs(s.ay) < 1 && Math.abs(s.by) < 1 && Math.abs(s.bx - photo.pixelWidth) < 2;
}

export function baselineAxes(
  photo: SurveyPhoto,
  base: PixelBaseline,
): { origin: Pt; along: Pt; east: Pt; headingAlong: number } {
  const a = pixelToWorld(photo, base.ax, base.ay);
  const b = pixelToWorld(photo, base.bx, base.by);
  const len = hypot(b.x - a.x, b.y - a.y) || 1;
  const along = { x: (b.x - a.x) / len, y: (b.y - a.y) / len };
  return { origin: a, along, east: { x: along.y, y: -along.x }, headingAlong: headingOf(a, b) };
}

/** Inches east of the west touchline, south along A→B. */
export function worldFromBaseline(photo: SurveyPhoto, base: PixelBaseline, eastInches: number, southInches: number): Pt {
  const { origin, along, east } = baselineAxes(photo, base);
  return {
    x: origin.x + southInches * along.x + eastInches * east.x,
    y: origin.y + southInches * along.y + eastInches * east.y,
  };
}
