/**
 * Van Soccer Association complex — left→right 12U, 10U, 6U/8U pack, 16U.
 * Schematic stamps are 300×120 yd. Aerial control is a surveyed baseline:
 * the painted 12U west touchline, north→south, 80 yd. Stamps live in that
 * frame (yards east of the west touchline, south of the north goal), so a
 * different crop still lands if the commissioner clicks that paint.
 */

import { baselineAxes, isFullWidthScale, worldFromBaseline, worldToPixel } from "./geometry";
import { addOverlay, cloneSurvey, placePhotosInEnu, setPhotoScale, surveyId } from "./ops";
import type { AssociationSurvey, PhotoGeodesy, PhotoScale, PixelBaseline, SurveyOverlay, SurveyPhoto } from "./types";
import { classSize, normHeading, yardsToInches } from "./units";
import type { NtssaClass } from "./units";

export const VAN_SCHEMATIC_YD = { width: 300, height: 120 };
export const VAN_SCHEMATIC_PX = { width: 1200, height: 480 };

export const VAN_COMPLEX_CAMPUS = {
  name: "Van Complex",
  association: "Van Rec",
  street: "445 S Oak St, Van, TX 75790",
  lat: 32.5243,
  lng: -95.6374,
};

interface Stamp {
  name: string;
  cls: NtssaClass;
  parking: string;
  cxYd: number;
  cyYd: number;
  headingDeg: number;
}

function stamps(): Stamp[] {
  const m = 8;
  const g = 5;
  const sx = m + 55 + g + 45 + g;
  const fx = sx + 25 + g + 25 + g;
  return [
    { name: "Van Complex 12U", cls: "nine", parking: "Lot South", cxYd: m + 27.5, cyYd: m + 40, headingDeg: 90 },
    { name: "Van Complex 10U", cls: "medium", parking: "Lot East", cxYd: m + 55 + g + 22.5, cyYd: m + 32.5, headingDeg: 90 },
    { name: "Van Complex 6U A", cls: "small", parking: "Lot North", cxYd: sx + 12.5, cyYd: m + 17.5, headingDeg: 90 },
    { name: "Van Complex 6U B", cls: "small", parking: "Lot North", cxYd: sx + 25 + g + 12.5, cyYd: m + 17.5, headingDeg: 90 },
    { name: "Van Complex 8U A", cls: "small", parking: "Lot North", cxYd: sx + 12.5, cyYd: m + 35 + g + 17.5, headingDeg: 90 },
    { name: "Van Complex 8U B", cls: "small", parking: "Lot North", cxYd: sx + 25 + g + 12.5, cyYd: m + 35 + g + 17.5, headingDeg: 90 },
    { name: "Van Complex 16U", cls: "full", parking: "Lot East", cxYd: fx + 55, cyYd: m + 35, headingDeg: 0 },
  ];
}

export function vanComplexPitchSpecs(): Array<{
  name: string;
  type: NtssaClass;
  campus: string;
  parking: string;
  availableRaw: string;
  cxYd: number;
  cyYd: number;
  headingDeg: number;
}> {
  return stamps().map((s) => ({
    name: s.name,
    type: s.cls,
    campus: "Van Complex",
    parking: s.parking,
    availableRaw: "Saturday 8:00–18:00",
    cxYd: s.cxYd,
    cyYd: s.cyYd,
    headingDeg: s.headingDeg,
  }));
}

export function vanLayoutOverlays(photoId: string, originInches = { x: 0, y: 0 }): SurveyOverlay[] {
  return stamps().map((s) => {
    const size = classSize(s.cls);
    return {
      id: surveyId("field"),
      photoId,
      fieldName: s.name,
      ntssaClass: s.cls,
      campus: "Van Complex",
      parking: s.parking,
      availableRaw: "Saturday 8:00-18:00",
      cxInches: originInches.x + yardsToInches(s.cxYd),
      cyInches: originInches.y + yardsToInches(s.cyYd),
      headingDeg: s.headingDeg,
      lengthInches: size.lengthInches,
      widthInches: size.widthInches,
      source: "van-layout",
    };
  });
}

export function placeVanLayout(survey: AssociationSurvey, photoId: string): AssociationSurvey {
  const photo = survey.photos.find((p) => p.id === photoId);
  if (!photo) return survey;
  let next = cloneSurvey(survey);
  next.overlays = next.overlays.filter((o) => !(o.photoId === photoId && o.source === "van-layout"));
  for (const o of vanLayoutOverlays(photoId, photo.worldOriginInches)) {
    next = addOverlay(next, o);
  }
  return next;
}

export function vanSchematicPhoto(dataUrl = ""): import("./types").SurveyPhoto {
  return {
    id: "photo-van-schematic",
    name: "Van Complex schematic",
    dataUrl,
    mime: "image/jpeg",
    pixelWidth: VAN_SCHEMATIC_PX.width,
    pixelHeight: VAN_SCHEMATIC_PX.height,
    scale: {
      ax: 0,
      ay: 0,
      bx: VAN_SCHEMATIC_PX.width,
      by: 0,
      knownInches: yardsToInches(VAN_SCHEMATIC_YD.width),
    },
    worldOriginInches: { x: 0, y: 0 },
    worldRotationDeg: 0,
  };
}

/**
 * Registered crop Soccer.png / public/van-aerial.jpg (2073×1069).
 * Used only when the commissioner has not clicked a 12U touchline on this photo.
 */
export const VAN_AERIAL_PX = { width: 2073, height: 1069 } as const;

/** West touchline of the painted 12U on that crop: north goal line → south goal line = 80 yd. */
const AERIAL_TOUCH_PX = { ax: 165, ay: 393, bx: 165, by: 821 };

interface AerialStamp {
  name: string;
  cls: NtssaClass;
  parking: string;
  /** Yards east of the west touchline, south of the north goal line — field center. */
  eastYd: number;
  southYd: number;
  /** 0 = length along the baseline (N–S on the Van nadir). */
  headingFromBaselineDeg: number;
}

function aerialStamps(): AerialStamp[] {
  const k = 80 / (AERIAL_TOUCH_PX.by - AERIAL_TOUCH_PX.ay);
  const es = (cxPx: number, cyPx: number) => ({
    eastYd: (cxPx - AERIAL_TOUCH_PX.ax) * k,
    southYd: (cyPx - AERIAL_TOUCH_PX.ay) * k,
  });
  const ten = es(968.5, 565);
  const sixA = es(1183, 413.5);
  const sixB = es(1343, 413.5);
  const eightA = es(1183, 627.5);
  const eightB = es(1343, 627.5);
  const full = es(1624, 542);
  return [
    { name: "Van Complex 12U", cls: "nine", parking: "Lot South", eastYd: 27.5, southYd: 40, headingFromBaselineDeg: 0 },
    { name: "Van Complex 10U", cls: "medium", parking: "Lot East", ...ten, headingFromBaselineDeg: 0 },
    { name: "Van Complex 6U A", cls: "small", parking: "Lot North", ...sixA, headingFromBaselineDeg: 0 },
    { name: "Van Complex 6U B", cls: "small", parking: "Lot North", ...sixB, headingFromBaselineDeg: 0 },
    { name: "Van Complex 8U A", cls: "small", parking: "Lot North", ...eightA, headingFromBaselineDeg: 0 },
    { name: "Van Complex 8U B", cls: "small", parking: "Lot North", ...eightB, headingFromBaselineDeg: 0 },
    { name: "Van Complex 16U", cls: "full", parking: "Lot East", ...full, headingFromBaselineDeg: 0 },
  ];
}

/** 12U center on the registered crop (west touchline + 27.5 yd, north goal + 40 yd). */
export const VAN_AERIAL_12U = {
  u: (AERIAL_TOUCH_PX.ax + 27.5 * (AERIAL_TOUCH_PX.by - AERIAL_TOUCH_PX.ay) / 80) / VAN_AERIAL_PX.width,
  v: (AERIAL_TOUCH_PX.ay + 40 * (AERIAL_TOUCH_PX.by - AERIAL_TOUCH_PX.ay) / 80) / VAN_AERIAL_PX.height,
  headingDeg: 90,
};

/** Google Maps pin on the registered crop, in the 12U baseline frame. Van Complex campus lat/lng. */
export const VAN_AERIAL_GCP = {
  eastYd: ((1033 - AERIAL_TOUCH_PX.ax) * 80) / (AERIAL_TOUCH_PX.by - AERIAL_TOUCH_PX.ay),
  southYd: ((252 - AERIAL_TOUCH_PX.ay) * 80) / (AERIAL_TOUCH_PX.by - AERIAL_TOUCH_PX.ay),
  lat: 32.5243,
  lng: -95.6374,
};

export function registeredBaseline(photo: SurveyPhoto): PixelBaseline {
  return {
    ax: (AERIAL_TOUCH_PX.ax / VAN_AERIAL_PX.width) * photo.pixelWidth,
    ay: (AERIAL_TOUCH_PX.ay / VAN_AERIAL_PX.height) * photo.pixelHeight,
    bx: (AERIAL_TOUCH_PX.bx / VAN_AERIAL_PX.width) * photo.pixelWidth,
    by: (AERIAL_TOUCH_PX.by / VAN_AERIAL_PX.height) * photo.pixelHeight,
  };
}

export function userTouchlineBaseline(photo: SurveyPhoto): PixelBaseline | null {
  const s = photo.scale;
  if (!s || isFullWidthScale(photo)) return null;
  if (Math.hypot(s.bx - s.ax, s.by - s.ay) < 8) return null;
  return { ax: s.ax, ay: s.ay, bx: s.bx, by: s.by };
}

export function vanAerialScale(photo: SurveyPhoto, base: PixelBaseline): PhotoScale {
  return { ...base, knownInches: yardsToInches(80) };
}

export function vanAerialGeodesy(photo: SurveyPhoto, base: PixelBaseline, campus?: { lat?: number; lng?: number }): PhotoGeodesy {
  const { headingAlong } = baselineAxes(photo, base);
  const pin = worldFromBaseline(photo, base, yardsToInches(VAN_AERIAL_GCP.eastYd), yardsToInches(VAN_AERIAL_GCP.southYd));
  const pix = worldToPixel(photo, pin);
  return {
    lat: campus?.lat ?? VAN_AERIAL_GCP.lat,
    lng: campus?.lng ?? VAN_AERIAL_GCP.lng,
    px: pix.x,
    py: pix.y,
    northDeg: normHeading(headingAlong + 180),
  };
}

export function vanAerialOverlays(photo: SurveyPhoto, base: PixelBaseline): SurveyOverlay[] {
  const { headingAlong } = baselineAxes(photo, base);
  return aerialStamps().map((s) => {
    const size = classSize(s.cls);
    const at = worldFromBaseline(photo, base, yardsToInches(s.eastYd), yardsToInches(s.southYd));
    return {
      id: surveyId("field"),
      photoId: photo.id,
      fieldName: s.name,
      ntssaClass: s.cls,
      campus: "Van Complex",
      parking: s.parking,
      availableRaw: "Saturday 8:00-18:00",
      cxInches: at.x,
      cyInches: at.y,
      headingDeg: normHeading(headingAlong + s.headingFromBaselineDeg),
      lengthInches: size.lengthInches,
      widthInches: size.widthInches,
      source: "van-aerial" as const,
    };
  });
}

/** 12U west touchline = 80 yd (user marks, or the registered crop), then official NTSSA stamps in that frame. */
export function fitVanAerial(
  survey: AssociationSurvey,
  photoId: string,
  campus?: { lat?: number; lng?: number },
): AssociationSurvey {
  const photo = survey.photos.find((p) => p.id === photoId);
  if (!photo) return survey;
  const user = userTouchlineBaseline(photo);
  const base = user || registeredBaseline(photo);
  const source: "user" | "registered" = user ? "user" : "registered";
  let next = cloneSurvey(survey);
  next.overlays = next.overlays.filter((o) => !(o.photoId === photoId && o.source === "van-aerial"));
  next = setPhotoScale(next, photoId, vanAerialScale(photo, base));
  const calibrated = next.photos.find((p) => p.id === photoId);
  if (!calibrated) return next;
  calibrated.baseline = { ...base };
  calibrated.baselineSource = source;
  calibrated.geodesy = vanAerialGeodesy(calibrated, base, campus);
  for (const o of vanAerialOverlays(calibrated, base)) {
    next = addOverlay(next, o);
  }
  return placePhotosInEnu(next);
}
