/** Object snap: corners, edge midpoints, and edge projections of other pitches. Grid is the fallback. */

import { fieldCorners, hypot, photoWorldSize } from "./geometry";
import type { AssociationSurvey, Pt, SurveyOverlay, SurveyPhoto } from "./types";
import { normHeading, yardsToInches } from "./units";

export const GEOM_SNAP_INCHES = yardsToInches(2.5);

export type SnapKind = "corner" | "mid" | "edge" | "center" | "photo";

export interface SnapTarget {
  p: Pt;
  kind: SnapKind;
  overlayId?: string;
}

function closestOnSegment(p: Pt, a: Pt, b: Pt): Pt {
  const dx = b.x - a.x;
  const dy = b.y - a.y;
  const len2 = dx * dx + dy * dy || 1;
  const t = Math.max(0, Math.min(1, ((p.x - a.x) * dx + (p.y - a.y) * dy) / len2));
  return { x: a.x + t * dx, y: a.y + t * dy };
}

export function overlaySnapPoints(o: SurveyOverlay, p?: Pt): SnapTarget[] {
  const c = fieldCorners(o);
  const mids: Pt[] = [
    { x: (c[0].x + c[1].x) / 2, y: (c[0].y + c[1].y) / 2 },
    { x: (c[1].x + c[2].x) / 2, y: (c[1].y + c[2].y) / 2 },
    { x: (c[2].x + c[3].x) / 2, y: (c[2].y + c[3].y) / 2 },
    { x: (c[3].x + c[0].x) / 2, y: (c[3].y + c[0].y) / 2 },
  ];
  const out: SnapTarget[] = [
    ...c.map((pt) => ({ p: pt, kind: "corner" as const, overlayId: o.id })),
    ...mids.map((pt) => ({ p: pt, kind: "mid" as const, overlayId: o.id })),
    { p: { x: o.cxInches, y: o.cyInches }, kind: "center", overlayId: o.id },
  ];
  if (p) {
    for (let i = 0; i < 4; i++) {
      out.push({ p: closestOnSegment(p, c[i], c[(i + 1) % 4]), kind: "edge", overlayId: o.id });
    }
  }
  return out;
}

export function photoSnapPoints(photo: SurveyPhoto): SnapTarget[] {
  const { w, h } = photoWorldSize(photo);
  const o = photo.worldOriginInches;
  const corners: Pt[] = [o, { x: o.x + w, y: o.y }, { x: o.x + w, y: o.y + h }, { x: o.x, y: o.y + h }];
  return [
    ...corners.map((p) => ({ p, kind: "photo" as const })),
    { p: { x: o.x + w / 2, y: o.y }, kind: "photo" },
    { p: { x: o.x + w, y: o.y + h / 2 }, kind: "photo" },
    { p: { x: o.x + w / 2, y: o.y + h }, kind: "photo" },
    { p: { x: o.x, y: o.y + h / 2 }, kind: "photo" },
  ];
}

export function nearestSnap(p: Pt, targets: SnapTarget[], threshold = GEOM_SNAP_INCHES): SnapTarget | null {
  let best: SnapTarget | null = null;
  let bestD = threshold;
  for (const t of targets) {
    const d = hypot(t.p.x - p.x, t.p.y - p.y);
    if (d <= bestD) {
      bestD = d;
      best = t;
    }
  }
  return best;
}

export function surveyTargets(survey: AssociationSurvey, p: Pt, excludeId?: string): SnapTarget[] {
  const hits: SnapTarget[] = [];
  for (const o of survey.overlays) {
    if (o.id === excludeId) continue;
    hits.push(...overlaySnapPoints(o, p));
  }
  for (const photo of survey.photos) hits.push(...photoSnapPoints(photo));
  return hits;
}

export function snapPointGeometry(survey: AssociationSurvey, p: Pt, excludeId?: string): Pt | null {
  const hit = nearestSnap(p, surveyTargets(survey, p, excludeId));
  return hit ? hit.p : null;
}

/** Translate an overlay so a corner or midpoint lands on another pitch. */
export function snapOverlayGeometry(survey: AssociationSurvey, o: SurveyOverlay): SurveyOverlay | null {
  const corners = fieldCorners(o);
  const mids: Pt[] = [
    { x: (corners[0].x + corners[1].x) / 2, y: (corners[0].y + corners[1].y) / 2 },
    { x: (corners[1].x + corners[2].x) / 2, y: (corners[1].y + corners[2].y) / 2 },
    { x: (corners[2].x + corners[3].x) / 2, y: (corners[2].y + corners[3].y) / 2 },
    { x: (corners[3].x + corners[0].x) / 2, y: (corners[3].y + corners[0].y) / 2 },
  ];
  const probes = [...corners, ...mids, { x: o.cxInches, y: o.cyInches }];
  let best: { dx: number; dy: number; dist: number } | null = null;
  for (const probe of probes) {
    const hit = nearestSnap(probe, surveyTargets(survey, probe, o.id));
    if (!hit) continue;
    const dx = hit.p.x - probe.x;
    const dy = hit.p.y - probe.y;
    const dist = hypot(dx, dy);
    if (!best || dist < best.dist) best = { dx, dy, dist };
  }
  if (!best) return null;
  const moved = { ...o, cxInches: o.cxInches + best.dx, cyInches: o.cyInches + best.dy };
  return { ...moved, headingDeg: snapHeading(survey, moved) };
}

/** Snap heading to a neighbor's edge or the cardinals, 5° grab. */
export function snapHeading(survey: AssociationSurvey, o: SurveyOverlay): number {
  const candidates = [0, 90, 180, 270];
  for (const n of survey.overlays) {
    if (n.id === o.id) continue;
    for (const off of [0, 90, 180, 270]) candidates.push(normHeading(n.headingDeg + off));
  }
  let best = o.headingDeg;
  let bestD = 5;
  for (const c of candidates) {
    let d = Math.abs(o.headingDeg - c) % 360;
    if (d > 180) d = 360 - d;
    if (d < bestD) {
      bestD = d;
      best = c;
    }
  }
  return best;
}
